CREATE DATABASE IF NOT EXISTS stocksense; USE stocksense;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('Admin','Inventory Manager','Warehouse Staff') DEFAULT 'Warehouse Staff',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) UNIQUE NOT NULL,description VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS warehouses(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,code VARCHAR(30) UNIQUE NOT NULL,address VARCHAR(255),status ENUM('Active','Inactive') DEFAULT 'Active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS locations(id INT AUTO_INCREMENT PRIMARY KEY,warehouse_id INT NOT NULL,name VARCHAR(120) NOT NULL,code VARCHAR(30) NOT NULL,description VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_loc(warehouse_id,code),FOREIGN KEY(warehouse_id) REFERENCES warehouses(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS products(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,sku VARCHAR(60) UNIQUE NOT NULL,category_id INT,unit_of_measure VARCHAR(30) NOT NULL DEFAULT 'pcs',reorder_level DECIMAL(12,2) DEFAULT 0,description TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS stock_levels(id INT AUTO_INCREMENT PRIMARY KEY,product_id INT NOT NULL,location_id INT NOT NULL,quantity DECIMAL(12,2) NOT NULL DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_stock(product_id,location_id),FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,FOREIGN KEY(location_id) REFERENCES locations(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS operations(id INT AUTO_INCREMENT PRIMARY KEY,operation_type ENUM('RECEIPT','DELIVERY','TRANSFER','ADJUSTMENT') NOT NULL,reference_number VARCHAR(50) UNIQUE NOT NULL,status ENUM('DRAFT','WAITING','READY','DONE','CANCELED') DEFAULT 'READY',source_location_id INT NULL,destination_location_id INT NULL,partner_name VARCHAR(150),notes TEXT,created_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(source_location_id) REFERENCES locations(id) ON DELETE SET NULL,FOREIGN KEY(destination_location_id) REFERENCES locations(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS operation_items(id INT AUTO_INCREMENT PRIMARY KEY,operation_id INT NOT NULL,product_id INT NOT NULL,quantity DECIMAL(12,2) NOT NULL,unit VARCHAR(30) NOT NULL DEFAULT 'pcs',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(operation_id) REFERENCES operations(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS stock_ledger(id INT AUTO_INCREMENT PRIMARY KEY,operation_id INT,product_id INT NOT NULL,from_location_id INT NULL,to_location_id INT NULL,quantity DECIMAL(12,2) NOT NULL,movement_type ENUM('RECEIPT','DELIVERY','TRANSFER','ADJUSTMENT_IN','ADJUSTMENT_OUT') NOT NULL,reference_number VARCHAR(50) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,created_by INT NULL,FOREIGN KEY(operation_id) REFERENCES operations(id) ON DELETE SET NULL,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE RESTRICT,FOREIGN KEY(from_location_id) REFERENCES locations(id) ON DELETE SET NULL,FOREIGN KEY(to_location_id) REFERENCES locations(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS reorder_rules(id INT AUTO_INCREMENT PRIMARY KEY,product_id INT NOT NULL,location_id INT NOT NULL,minimum_quantity DECIMAL(12,2) DEFAULT 0,maximum_quantity DECIMAL(12,2) DEFAULT 0,reorder_quantity DECIMAL(12,2) DEFAULT 0,UNIQUE KEY uq_reorder(product_id,location_id),FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,FOREIGN KEY(location_id) REFERENCES locations(id) ON DELETE CASCADE);
CREATE INDEX idx_ops ON operations(operation_type,status); CREATE INDEX idx_ledger ON stock_ledger(created_at);
